import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link HypergeometricDistribution#getNumericalMean()}.
 */
public class HypergeometricDistribution_getNumericalMean_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetNumericalMean_StandardCase() {
        // populationSize = 100, numberOfSuccesses = 20, sampleSize = 10
        // Mean = (10 * 20) / 100 = 2.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(100, 20, 10);
        double expected = 2.0;
        double actual = distribution.getNumericalMean();
        Assert.assertEquals("The numerical mean should be correct for standard parameters.", expected, actual, EPSILON);
    }












}

