import static org.junit.Assert.*;

/**
 * Unit tests for {@link HypergeometricDistribution#getNumericalMean()}.
 */
public class HypergeometricDistribution_getNumericalMean_TriageGen1Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testGetNumericalMean_FloatingPointPrecision() {
        // populationSize = 3, numberOfSuccesses = 1, sampleSize = 1
        // Mean = (1 * 1) / 3 = 0.3333333333333333
        HypergeometricDistribution distribution = new HypergeometricDistribution(3, 1, 1);
        double expected = 1.0 / 3.0;
        double actual = distribution.getNumericalMean();
        Assert.assertEquals("The numerical mean should maintain double precision.", expected, actual, EPSILON);
    }
}
